-- Canonical Sprachtreppe Next classroom backend (bigint IDs shared by Flutter and web).
-- Historical LMS migrations 001-012 use incompatible UUID IDs; do not apply them to Next.
begin;
alter table public.profiles drop constraint if exists profiles_role_check;
alter table public.profiles add constraint profiles_role_check check(role in('student','teacher','admin'));
create table if not exists public.classes(id bigint generated by default as identity primary key,name text not null check(char_length(trim(name)) between 1 and 100),description text not null default '',level text,archived boolean not null default false,created_by uuid not null default auth.uid() references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.class_teachers(class_id bigint not null references public.classes(id) on delete cascade,teacher_id uuid not null references public.profiles(id) on delete cascade,assigned_by uuid not null references public.profiles(id) on delete restrict,assigned_at timestamptz not null default now(),primary key(class_id,teacher_id));
create table if not exists public.class_members(class_id bigint not null references public.classes(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,enrolled_by uuid references public.profiles(id) on delete set null,enrolled_at timestamptz not null default now(),primary key(class_id,student_id));
create table if not exists public.teacher_students(teacher_id uuid not null references public.profiles(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,assigned_by uuid not null default auth.uid() references public.profiles(id) on delete restrict,assigned_at timestamptz not null default now(),primary key(teacher_id,student_id),check(teacher_id<>student_id));
create table if not exists public.assignments(id bigint generated by default as identity primary key,class_id bigint references public.classes(id) on delete cascade,title text not null check(char_length(trim(title)) between 1 and 120),instructions text not null default '' check(char_length(instructions)<=2000),kind text not null default 'practice' check(char_length(kind) between 1 and 40),skill text not null default 'mixed' check(char_length(skill) between 1 and 30),target_count integer not null default 10 check(target_count between 1 and 1000),due_at timestamptz,archived boolean not null default false,created_by uuid not null default auth.uid() references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.assignment_progress(assignment_id bigint not null references public.assignments(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,done integer not null default 0 check(done>=0),correct integer not null default 0 check(correct>=0 and correct<=done),completed_at timestamptz,updated_at timestamptz not null default now(),primary key(assignment_id,student_id));
create table if not exists public.announcements(id bigint generated by default as identity primary key,class_id bigint references public.classes(id) on delete cascade,title text not null check(char_length(trim(title)) between 1 and 120),body text not null check(char_length(body) between 1 and 2000),pinned boolean not null default false,expires_at timestamptz,created_by uuid not null default auth.uid() references public.profiles(id) on delete restrict,created_at timestamptz not null default now());
create table if not exists public.audit_log(id bigint generated by default as identity primary key,at timestamptz not null default now(),actor_id uuid references public.profiles(id) on delete set null,actor_email text not null default '',action text not null check(char_length(action) between 1 and 100),target_type text not null default 'system',target_id text,details jsonb not null default '{}'::jsonb);
create table if not exists public.notifications(id bigint generated always as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,kind text not null default 'info',title text not null check(char_length(trim(title)) between 1 and 180),body text not null default '',link text,read_at timestamptz,created_at timestamptz not null default now());
create index if not exists classes_active_name_idx on public.classes(archived,name);
create index if not exists class_teachers_teacher_idx on public.class_teachers(teacher_id,class_id);
create index if not exists class_members_student_idx on public.class_members(student_id,class_id);
create index if not exists teacher_students_student_idx on public.teacher_students(student_id);
create index if not exists assignments_class_created_idx on public.assignments(class_id,created_at desc) where not archived;
create index if not exists assignments_created_by_idx on public.assignments(created_by,created_at desc) where not archived;
create index if not exists assignment_progress_student_updated_idx on public.assignment_progress(student_id,updated_at desc);
create index if not exists announcements_class_created_idx on public.announcements(class_id,created_at desc);
create index if not exists audit_log_at_idx on public.audit_log(at desc);
create index if not exists notifications_user_created_idx on public.notifications(user_id,created_at desc);
alter table public.classes enable row level security; alter table public.class_teachers enable row level security; alter table public.class_members enable row level security; alter table public.teacher_students enable row level security; alter table public.assignments enable row level security; alter table public.assignment_progress enable row level security; alter table public.announcements enable row level security; alter table public.audit_log enable row level security; alter table public.notifications enable row level security;

create or replace function public.is_approved_student() returns boolean language sql stable security definer set search_path='' as $fn$ select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='student' and p.approved); $fn$;
create or replace function public.is_teacher() returns boolean language sql stable security definer set search_path='' as $fn$ select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='teacher' and p.approved); $fn$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path='' as $fn$ select public.is_admin() or public.is_teacher(); $fn$;
create or replace function public.is_class_teacher(p_class bigint) returns boolean language sql stable security definer set search_path='' as $fn$ select p_class is not null and exists(select 1 from public.class_teachers ct where ct.class_id=p_class and ct.teacher_id=auth.uid()); $fn$;
create or replace function public.is_class_member(p_class bigint) returns boolean language sql stable security definer set search_path='' as $fn$ select p_class is not null and exists(select 1 from public.class_members cm where cm.class_id=p_class and cm.student_id=auth.uid()); $fn$;

drop policy if exists classes_select on public.classes;
create policy classes_select on public.classes for select to authenticated using(public.is_admin() or public.is_class_teacher(id) or public.is_class_member(id));
drop policy if exists class_teachers_select on public.class_teachers; drop policy if exists "teachers can read their class assignments" on public.class_teachers;
create policy class_teachers_select on public.class_teachers for select to authenticated using(public.is_admin() or teacher_id=(select auth.uid()));
drop policy if exists class_members_select on public.class_members;
create policy class_members_select on public.class_members for select to authenticated using(public.is_admin() or student_id=(select auth.uid()) or public.is_class_teacher(class_id));
drop policy if exists teacher_students_select on public.teacher_students;
create policy teacher_students_select on public.teacher_students for select to authenticated using(public.is_admin() or teacher_id=(select auth.uid()) or student_id=(select auth.uid()));
drop policy if exists assignments_select on public.assignments; drop policy if exists assignments_teacher_select on public.assignments;
create policy assignments_select on public.assignments for select to authenticated using(public.is_admin() or (public.is_teacher() and (created_by=(select auth.uid()) or public.is_class_teacher(class_id))) or (public.is_approved_student() and (class_id is null or public.is_class_member(class_id))));
drop policy if exists assignments_admin_insert on public.assignments;
create policy assignments_admin_insert on public.assignments for insert to authenticated with check(public.is_admin() and created_by=(select auth.uid()) and (class_id is null or exists(select 1 from public.classes c where c.id=class_id and not c.archived)));
drop policy if exists assignment_progress_select on public.assignment_progress;
create policy assignment_progress_select on public.assignment_progress for select to authenticated using(public.is_admin() or student_id=(select auth.uid()) or exists(select 1 from public.assignments a where a.id=assignment_id and (a.created_by=(select auth.uid()) or public.is_class_teacher(a.class_id))));
drop policy if exists announcements_select on public.announcements;
create policy announcements_select on public.announcements for select to authenticated using(public.is_admin() or (public.is_teacher() and (class_id is null or public.is_class_teacher(class_id))) or (public.is_approved_student() and (class_id is null or public.is_class_member(class_id))));
drop policy if exists announcements_insert_staff on public.announcements;
create policy announcements_insert_staff on public.announcements for insert to authenticated with check(created_by=(select auth.uid()) and ((public.is_admin() and (class_id is null or exists(select 1 from public.classes c where c.id=class_id and not c.archived))) or (public.is_teacher() and class_id is not null and public.is_class_teacher(class_id))));
drop policy if exists audit_log_staff_select on public.audit_log;
create policy audit_log_staff_select on public.audit_log for select to authenticated using(public.is_admin() or actor_id=(select auth.uid()) or (public.is_teacher() and target_id in(select ts.student_id::text from public.teacher_students ts where ts.teacher_id=(select auth.uid()))));
drop policy if exists notifications_select_own on public.notifications; drop policy if exists notifications_update_read_own on public.notifications; drop policy if exists notifications_update_own on public.notifications;
create policy notifications_select_own on public.notifications for select to authenticated using(user_id=(select auth.uid()));
create policy notifications_update_read_own on public.notifications for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
revoke all on public.classes,public.class_teachers,public.class_members,public.teacher_students,public.assignments,public.assignment_progress,public.announcements,public.audit_log,public.notifications from public,anon,authenticated;
grant select on public.classes,public.class_teachers,public.class_members,public.teacher_students,public.assignment_progress,public.audit_log,public.notifications to authenticated;
grant select,insert on public.assignments,public.announcements to authenticated; grant update(read_at) on public.notifications to authenticated;
grant usage,select on sequence public.classes_id_seq,public.assignments_id_seq,public.announcements_id_seq to authenticated;

create or replace function public.create_class(p_name text) returns bigint language plpgsql security definer set search_path='' as $fn$ declare v_id bigint; v_name text:=trim(coalesce(p_name,'')); begin
 if not public.is_admin() then raise exception 'forbidden' using errcode='42501'; end if; if char_length(v_name) not between 1 and 100 then raise exception 'class name must be 1-100 characters' using errcode='22023'; end if;
 insert into public.classes(name,created_by) values(v_name,auth.uid()) returning id into v_id;
 insert into public.audit_log(actor_id,actor_email,action,target_type,target_id,details) select p.id,p.email,'create_class','class',v_id::text,jsonb_build_object('name',v_name) from public.profiles p where p.id=auth.uid(); return v_id; end; $fn$;
create or replace function public.assign_teacher(p_email text) returns uuid language plpgsql security definer set search_path='' as $fn$ declare v_id uuid; v_email text:=lower(trim(coalesce(p_email,''))); begin
 if not public.is_admin() then raise exception 'forbidden' using errcode='42501'; end if; if v_email='' then raise exception 'teacher email is required' using errcode='22023'; end if;
 select p.id into v_id from public.profiles p where lower(p.email)=v_email; if v_id is null then raise exception 'teacher account not found' using errcode='P0002'; end if;
 if exists(select 1 from public.profiles p where p.id=v_id and p.role='admin') then raise exception 'an administrator cannot be changed into a teacher' using errcode='42501'; end if;
 update public.profiles set role='teacher',approved=true where id=v_id;
 insert into public.audit_log(actor_id,actor_email,action,target_type,target_id,details) select p.id,p.email,'assign_teacher','profile',v_id::text,jsonb_build_object('email',v_email) from public.profiles p where p.id=auth.uid(); return v_id; end; $fn$;
create or replace function public.assign_teacher_to_class(p_class bigint,p_teacher uuid) returns void language plpgsql security definer set search_path='' as $fn$ begin
 if not public.is_admin() then raise exception 'forbidden' using errcode='42501'; end if;
 if not exists(select 1 from public.classes c where c.id=p_class and not c.archived) then raise exception 'class not found' using errcode='P0002'; end if;
 if not exists(select 1 from public.profiles p where p.id=p_teacher and p.role='teacher' and p.approved) then raise exception 'teacher not found or not approved' using errcode='22023'; end if;
 insert into public.class_teachers(class_id,teacher_id,assigned_by) values(p_class,p_teacher,auth.uid()) on conflict do nothing;
 insert into public.class_members(class_id,student_id,enrolled_by) select p_class,ts.student_id,auth.uid() from public.teacher_students ts where ts.teacher_id=p_teacher on conflict do nothing;
 insert into public.audit_log(actor_id,actor_email,action,target_type,target_id,details) select p.id,p.email,'assign_teacher_to_class','class',p_class::text,jsonb_build_object('teacher_id',p_teacher) from public.profiles p where p.id=auth.uid(); end; $fn$;
create or replace function public.assign_student_to_teacher(p_teacher uuid,p_student uuid) returns void language plpgsql security definer set search_path='' as $fn$ declare v_count integer; begin
 if not public.is_admin() then raise exception 'forbidden' using errcode='42501'; end if;
 if not exists(select 1 from public.profiles p where p.id=p_teacher and p.role='teacher' and p.approved) then raise exception 'teacher not found or not approved'; end if;
 if not exists(select 1 from public.profiles p where p.id=p_student and p.role='student' and p.approved) then raise exception 'student not found or not approved'; end if;
 insert into public.teacher_students(teacher_id,student_id,assigned_by) values(p_teacher,p_student,auth.uid()) on conflict do nothing; get diagnostics v_count=row_count;
 insert into public.class_members(class_id,student_id,enrolled_by) select ct.class_id,p_student,auth.uid() from public.class_teachers ct join public.classes c on c.id=ct.class_id where ct.teacher_id=p_teacher and not c.archived on conflict do nothing;
 if v_count>0 then insert into public.notifications(user_id,kind,title,body,link) values(p_student,'teacher_assignment','Teacher assigned','You have been assigned to a teacher.','#/classroom');
 insert into public.audit_log(actor_id,actor_email,action,target_type,target_id,details) select p.id,p.email,'assign_student_to_teacher','student',p_student::text,jsonb_build_object('teacher_id',p_teacher) from public.profiles p where p.id=auth.uid(); end if; end; $fn$;
create or replace function public.remove_student_from_teacher(p_teacher uuid,p_student uuid) returns void language plpgsql security definer set search_path='' as $fn$ declare v_count integer; begin
 if not public.is_admin() then raise exception 'forbidden' using errcode='42501'; end if; delete from public.teacher_students where teacher_id=p_teacher and student_id=p_student; get diagnostics v_count=row_count;
 delete from public.class_members cm using public.class_teachers ct where ct.teacher_id=p_teacher and ct.class_id=cm.class_id and cm.student_id=p_student and not exists(select 1 from public.class_teachers oct join public.teacher_students ots on ots.teacher_id=oct.teacher_id where oct.class_id=cm.class_id and ots.student_id=p_student and oct.teacher_id<>p_teacher);
 if v_count>0 then insert into public.notifications(user_id,kind,title,body,link) values(p_student,'teacher_assignment_removed','Teacher assignment removed','You are no longer assigned to that teacher.','#/classroom');
 insert into public.audit_log(actor_id,actor_email,action,target_type,target_id,details) select p.id,p.email,'remove_student_from_teacher','student',p_student::text,jsonb_build_object('teacher_id',p_teacher) from public.profiles p where p.id=auth.uid(); end if; end; $fn$;
create or replace function public.remove_my_student(p_student uuid) returns void language plpgsql security definer set search_path='' as $fn$ declare v_count integer; begin
 if not public.is_teacher() then raise exception 'forbidden' using errcode='42501'; end if; delete from public.teacher_students where teacher_id=auth.uid() and student_id=p_student; get diagnostics v_count=row_count;
 delete from public.class_members cm using public.class_teachers ct where ct.teacher_id=auth.uid() and ct.class_id=cm.class_id and cm.student_id=p_student and not exists(select 1 from public.class_teachers oct join public.teacher_students ots on ots.teacher_id=oct.teacher_id where oct.class_id=cm.class_id and ots.student_id=p_student and oct.teacher_id<>auth.uid());
 if v_count>0 then insert into public.notifications(user_id,kind,title,body,link) values(p_student,'teacher_assignment_removed','Teacher assignment removed','You are no longer assigned to your teacher.','#/classroom');
 insert into public.audit_log(actor_id,actor_email,action,target_type,target_id,details) select p.id,p.email,'remove_my_student','student',p_student::text,'{}'::jsonb from public.profiles p where p.id=auth.uid(); end if; end; $fn$;
create or replace function public.my_students() returns jsonb language plpgsql stable security definer set search_path='' as $fn$ declare v_result jsonb; begin
 if not public.is_teacher() then raise exception 'forbidden' using errcode='42501'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'full_name',p.full_name,'email',p.email,'approved',p.approved,'assigned_at',ts.assigned_at,'assignment_count',coalesce(x.assignment_count,0),'completed_assignments',coalesce(x.completed_assignments,0),'done',coalesce(x.done,0),'correct',coalesce(x.correct,0),'last_activity',x.last_activity) order by p.full_name,p.email),'[]'::jsonb)
 into v_result from public.teacher_students ts join public.profiles p on p.id=ts.student_id left join lateral(select count(a.id)::int assignment_count,count(a.id) filter(where ap.completed_at is not null)::int completed_assignments,coalesce(sum(ap.done),0)::int done,coalesce(sum(ap.correct),0)::int correct,max(ap.updated_at) last_activity from public.assignments a left join public.assignment_progress ap on ap.assignment_id=a.id and ap.student_id=p.id where not a.archived and (a.class_id is null or exists(select 1 from public.class_members cm where cm.class_id=a.class_id and cm.student_id=p.id))) x on true where ts.teacher_id=auth.uid() and p.role='student'; return v_result; end; $fn$;
create or replace function public.admin_students_overview() returns jsonb language plpgsql stable security definer set search_path='' as $fn$ declare v_result jsonb; begin
 if not public.is_admin() then raise exception 'forbidden' using errcode='42501'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'full_name',p.full_name,'email',p.email,'approved',p.approved,'teachers',coalesce(t.items,'[]'::jsonb),'classes',coalesce(c.items,'[]'::jsonb),'assignment_count',coalesce(x.assignment_count,0),'completed_assignments',coalesce(x.completed_assignments,0),'done',coalesce(x.done,0),'correct',coalesce(x.correct,0),'last_activity',x.last_activity,'pending_submissions',coalesce(s.pending_submissions,0)) order by p.full_name,p.email),'[]'::jsonb)
 into v_result from public.profiles p left join lateral(select jsonb_agg(jsonb_build_object('id',tp.id,'name',coalesce(nullif(tp.full_name,''),tp.email)) order by tp.full_name,tp.email) items from public.teacher_students ts join public.profiles tp on tp.id=ts.teacher_id where ts.student_id=p.id) t on true
 left join lateral(select jsonb_agg(jsonb_build_object('id',cl.id,'name',cl.name) order by cl.name) items from public.class_members cm join public.classes cl on cl.id=cm.class_id where cm.student_id=p.id and not cl.archived) c on true
 left join lateral(select count(a.id)::int assignment_count,count(a.id) filter(where ap.completed_at is not null)::int completed_assignments,coalesce(sum(ap.done),0)::int done,coalesce(sum(ap.correct),0)::int correct,max(ap.updated_at) last_activity from public.assignments a left join public.assignment_progress ap on ap.assignment_id=a.id and ap.student_id=p.id where not a.archived and (a.class_id is null or exists(select 1 from public.class_members cm where cm.class_id=a.class_id and cm.student_id=p.id))) x on true
 left join lateral(select count(*) filter(where sub.review_status='pending')::int pending_submissions from public.submissions sub where sub.student_id=p.id) s on true where p.role='student'; return v_result; end; $fn$;
create or replace function public.staff_audit(p_limit integer default 100) returns jsonb language plpgsql stable security definer set search_path='' as $fn$ declare v_result jsonb; v_limit integer:=greatest(1,least(coalesce(p_limit,100),200)); begin
 if not public.is_staff() then raise exception 'forbidden' using errcode='42501'; end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by q.at desc),'[]'::jsonb) into v_result from(select a.id,a.at,a.actor_id,a.actor_email,a.action,a.target_type,a.target_id,a.details from public.audit_log a where public.is_admin() or a.actor_id=auth.uid() or a.target_id in(select ts.student_id::text from public.teacher_students ts where ts.teacher_id=auth.uid()) order by a.at desc limit v_limit) q; return v_result; end; $fn$;
create or replace function public.my_classroom() returns jsonb language plpgsql stable security definer set search_path='' as $fn$ declare v_uid uuid:=auth.uid(); v_role text; v_approved boolean; begin
 if v_uid is null then raise exception 'not authenticated' using errcode='28000'; end if; select p.role,p.approved into v_role,v_approved from public.profiles p where p.id=v_uid;
 if not found or not v_approved then raise exception 'account not approved' using errcode='42501'; end if;
 return jsonb_build_object(
 'classes',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived) order by c.name) from public.classes c where not c.archived and (v_role='admin' or (v_role='teacher' and exists(select 1 from public.class_teachers ct where ct.class_id=c.id and ct.teacher_id=v_uid)) or (v_role='student' and exists(select 1 from public.class_members cm where cm.class_id=c.id and cm.student_id=v_uid)))),'[]'::jsonb),
 'assignments',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'class_id',a.class_id,'title',a.title,'instructions',a.instructions,'kind',a.kind,'skill',a.skill,'target_count',a.target_count,'due_at',a.due_at,'created_at',a.created_at,'created_by',a.created_by,'archived',a.archived,'class_name',c.name,'done',coalesce(ap.done,0),'correct',coalesce(ap.correct,0),'completed_count',coalesce(ap.done,0)) order by a.created_at desc) from public.assignments a left join public.classes c on c.id=a.class_id left join public.assignment_progress ap on ap.assignment_id=a.id and ap.student_id=v_uid where not a.archived and (v_role='admin' or (v_role='teacher' and (a.created_by=v_uid or exists(select 1 from public.class_teachers ct where ct.class_id=a.class_id and ct.teacher_id=v_uid))) or (v_role='student' and (a.class_id is null or exists(select 1 from public.class_members cm where cm.class_id=a.class_id and cm.student_id=v_uid))))),'[]'::jsonb),
 'announcements',coalesce((select jsonb_agg(jsonb_build_object('id',an.id,'class_id',an.class_id,'title',an.title,'body',an.body,'pinned',an.pinned,'expires_at',an.expires_at,'created_by',an.created_by,'created_at',an.created_at) order by an.pinned desc,an.created_at desc) from public.announcements an where (an.expires_at is null or an.expires_at>now()) and (v_role='admin' or (v_role='teacher' and (an.class_id is null or exists(select 1 from public.class_teachers ct where ct.class_id=an.class_id and ct.teacher_id=v_uid))) or (v_role='student' and (an.class_id is null or exists(select 1 from public.class_members cm where cm.class_id=an.class_id and cm.student_id=v_uid))))),'[]'::jsonb)); end; $fn$;
create or replace function public.create_assignment(p_class bigint,p_title text,p_instructions text,p_skill text,p_target integer,p_due timestamptz) returns bigint language plpgsql security definer set search_path='' as $fn$ declare v_id bigint; v_title text:=trim(coalesce(p_title,'')); v_instructions text:=coalesce(p_instructions,''); begin
 if not public.is_staff() then raise exception 'forbidden' using errcode='42501'; end if; if char_length(v_title) not between 1 and 120 then raise exception 'invalid assignment title' using errcode='22023'; end if;
 if char_length(v_instructions)>2000 then raise exception 'instructions exceed 2000 characters' using errcode='22023'; end if; if coalesce(p_target,0) not between 1 and 1000 then raise exception 'target must be 1-1000' using errcode='22023'; end if;
 if p_class is null then if not public.is_admin() then raise exception 'teachers must choose a class' using errcode='42501'; end if;
 elsif not exists(select 1 from public.classes c where c.id=p_class and not c.archived) then raise exception 'class not found' using errcode='P0002';
 elsif not public.is_admin() and not public.is_class_teacher(p_class) then raise exception 'not assigned to class' using errcode='42501'; end if;
 insert into public.assignments(class_id,title,instructions,kind,skill,target_count,due_at,created_by) values(p_class,v_title,v_instructions,'practice',coalesce(nullif(trim(p_skill),''),'mixed'),p_target,p_due,auth.uid()) returning id into v_id;
 insert into public.audit_log(actor_id,actor_email,action,target_type,target_id,details) select p.id,p.email,'create_assignment','assignment',v_id::text,jsonb_build_object('title',v_title,'class_id',p_class,'target_count',p_target) from public.profiles p where p.id=auth.uid(); return v_id; end; $fn$;
create or replace function public.assignment_status(p_id bigint) returns table(student_id uuid,full_name text,email text,done integer,correct integer,completed_at timestamptz,updated_at timestamptz) language plpgsql stable security definer set search_path='' as $fn$ declare v_assignment public.assignments%rowtype; begin
 if not public.is_staff() then raise exception 'forbidden' using errcode='42501'; end if; select * into v_assignment from public.assignments a where a.id=p_id and not a.archived;
 if not found then raise exception 'assignment not found' using errcode='P0002'; end if; if not public.is_admin() and not(v_assignment.created_by=auth.uid() or public.is_class_teacher(v_assignment.class_id)) then raise exception 'forbidden' using errcode='42501'; end if;
 return query select p.id,p.full_name,p.email,coalesce(ap.done,0),coalesce(ap.correct,0),ap.completed_at,ap.updated_at from public.profiles p left join public.assignment_progress ap on ap.assignment_id=p_id and ap.student_id=p.id where p.role='student' and p.approved and (v_assignment.class_id is null or exists(select 1 from public.class_members cm where cm.class_id=v_assignment.class_id and cm.student_id=p.id)) order by p.full_name,p.email; end; $fn$;
create or replace function public.update_assignment_progress(p_assignment bigint,p_done integer,p_correct integer) returns void language plpgsql security definer set search_path='' as $fn$ declare v_uid uuid:=auth.uid(); v_assignment public.assignments%rowtype; begin
 if v_uid is null or not public.is_approved_student() then raise exception 'forbidden' using errcode='42501'; end if; select * into v_assignment from public.assignments a where a.id=p_assignment and not a.archived;
 if not found then raise exception 'assignment not found' using errcode='P0002'; end if; if v_assignment.class_id is not null and not public.is_class_member(v_assignment.class_id) then raise exception 'not a class member' using errcode='42501'; end if;
 if p_done is null or p_correct is null or p_done<0 or p_done>v_assignment.target_count or p_correct<0 or p_correct>p_done then raise exception 'invalid progress values' using errcode='22023'; end if;
 insert into public.assignment_progress(assignment_id,student_id,done,correct,completed_at,updated_at) values(p_assignment,v_uid,p_done,p_correct,case when p_done>=v_assignment.target_count then now() else null end,now())
 on conflict(assignment_id,student_id) do update set done=greatest(public.assignment_progress.done,excluded.done),correct=least(greatest(public.assignment_progress.correct,excluded.correct),greatest(public.assignment_progress.done,excluded.done)),completed_at=case when greatest(public.assignment_progress.done,excluded.done)>=v_assignment.target_count then coalesce(public.assignment_progress.completed_at,now()) else null end,updated_at=now(); end; $fn$;

create or replace function public.notify_assignment_recipients() returns trigger language plpgsql security definer set search_path='' as $fn$ begin
 insert into public.notifications(user_id,kind,title,body,link) select distinct p.id,'assignment_assigned','New assignment: '||new.title,'A new assignment has been assigned to you.','#/assignments' from public.profiles p where p.role='student' and p.approved and (new.class_id is null or exists(select 1 from public.class_members cm where cm.class_id=new.class_id and cm.student_id=p.id)); return new; end; $fn$;
drop trigger if exists assignments_notify_recipients on public.assignments;
create trigger assignments_notify_recipients after insert on public.assignments for each row execute function public.notify_assignment_recipients();
create or replace function public.notify_announcement_recipients() returns trigger language plpgsql security definer set search_path='' as $fn$ begin
 insert into public.notifications(user_id,kind,title,body,link) select distinct p.id,'announcement','Announcement: '||new.title,left(new.body,500),'#/home' from public.profiles p where p.role='student' and p.approved and (new.class_id is null or exists(select 1 from public.class_members cm where cm.class_id=new.class_id and cm.student_id=p.id)); return new; end; $fn$;
drop trigger if exists announcements_notify_recipients on public.announcements;
create trigger announcements_notify_recipients after insert on public.announcements for each row execute function public.notify_announcement_recipients();
create or replace function public.assignment_progress_events() returns trigger language plpgsql security definer set search_path='' as $fn$ declare v_old_complete boolean:=false; v_assignment public.assignments%rowtype; begin
 if tg_op='UPDATE' then v_old_complete:=old.completed_at is not null; end if; if new.completed_at is not null and not v_old_complete then
 select * into v_assignment from public.assignments a where a.id=new.assignment_id;
 insert into public.notifications(user_id,kind,title,body,link) values(new.student_id,'assignment_submission','Assignment completed','Your assignment "'||coalesce(v_assignment.title,'Assignment')||'" is complete.','#/assignments');
 insert into public.notifications(user_id,kind,title,body,link) select distinct rec.user_id,'student_submission','Student completed an assignment',coalesce(nullif(p.full_name,''),p.email,'A student')||' completed "'||coalesce(v_assignment.title,'Assignment')||'".','#/assignments' from (select ts.teacher_id user_id from public.teacher_students ts where ts.student_id=new.student_id union select ct.teacher_id from public.class_teachers ct join public.class_members cm on cm.class_id=ct.class_id where cm.student_id=new.student_id and (v_assignment.class_id is null or ct.class_id=v_assignment.class_id)) rec join public.profiles p on p.id=new.student_id;
 insert into public.audit_log(actor_id,actor_email,action,target_type,target_id,details) select p.id,p.email,'assignment_completed','assignment',new.assignment_id::text,jsonb_build_object('student_id',new.student_id,'done',new.done,'correct',new.correct) from public.profiles p where p.id=new.student_id;
 end if; return new; end; $fn$;
drop trigger if exists assignment_progress_events_after_write on public.assignment_progress;
create trigger assignment_progress_events_after_write after insert or update on public.assignment_progress for each row execute function public.assignment_progress_events();
create or replace function public.notify_written_submission() returns trigger language plpgsql security definer set search_path='' as $fn$ begin
 if new.payload ? 'assignment_response' or new.summary->>'source'='flutter_assignment_response' then
 insert into public.notifications(user_id,kind,title,body,link) select p.id,'written_submission','Written work awaiting review',coalesce(nullif(new.payload #>> '{assignment_response,title}',''),'A student submitted written work.'),'#/admin' from public.profiles p where p.role='admin' and p.approved;
 insert into public.notifications(user_id,kind,title,body,link) select distinct rec.user_id,'written_submission','Student submitted written work',coalesce(nullif(new.payload #>> '{assignment_response,title}',''),'A student submitted written work.'),'#/assignments' from (select ts.teacher_id user_id from public.teacher_students ts where ts.student_id=new.student_id union select ct.teacher_id from public.class_teachers ct join public.class_members cm on cm.class_id=ct.class_id where cm.student_id=new.student_id) rec where rec.user_id is not null; end if;
 insert into public.audit_log(actor_id,actor_email,action,target_type,target_id,details) select p.id,p.email,'submit_progress','submission',new.id::text,jsonb_build_object('review_status',new.review_status,'summary',new.summary) from public.profiles p where p.id=new.student_id; return new; end; $fn$;
drop trigger if exists submissions_notify_written on public.submissions;
create trigger submissions_notify_written after insert on public.submissions for each row execute function public.notify_written_submission();
create or replace function public.notify_submission_review() returns trigger language plpgsql security definer set search_path='' as $fn$ begin
 if not new.student_seen then insert into public.notifications(user_id,kind,title,body,link) values(new.student_id,'teacher_feedback','Your work was reviewed',coalesce(nullif(new.review_note,''),'Your teacher/admin has reviewed your progress.'),'#/account'); end if; return new; end; $fn$;
drop trigger if exists submissions_notify_review on public.submissions;
create trigger submissions_notify_review after update of review_status,review_note,rating,student_seen on public.submissions for each row
when(old.review_status is distinct from new.review_status or old.review_note is distinct from new.review_note or old.rating is distinct from new.rating or old.student_seen is distinct from new.student_seen)
execute function public.notify_submission_review();

create or replace function public.submit_progress(p_payload jsonb,p_client_id text)
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare v_uid uuid:=auth.uid(); v_prof public.profiles%rowtype; v_recent integer; v_id bigint; v_entry record; v_write jsonb; v_assignment public.assignments%rowtype; v_assignment_id bigint; v_done integer; v_correct integer; v_target integer; v_writing_count integer:=0; v_write_client text; v_response text; v_submitted_at timestamptz;
begin
 if v_uid is null then raise exception 'not authenticated' using errcode='28000'; end if; select * into v_prof from public.profiles p where p.id=v_uid;
 if not found or not v_prof.approved then raise exception 'account not approved' using errcode='42501'; end if;
 if v_prof.role='admin' then return jsonb_build_object('ok',true,'server_time',now(),'skipped','admin','feedback','[]'::jsonb); end if;
 if p_client_id is null or char_length(p_client_id) not between 8 and 64 then raise exception 'bad client id' using errcode='22023'; end if;
 if p_payload is null or jsonb_typeof(p_payload)<>'object' or jsonb_typeof(p_payload->'summary')<>'object' then raise exception 'bad payload' using errcode='22023'; end if;
 if octet_length(p_payload::text)>600000 then raise exception 'payload too large' using errcode='54000'; end if;
 select count(*)::integer into v_recent from public.submissions s where s.student_id=v_uid and s.created_at>now()-interval '1 day';
 select count(*)::integer into v_writing_count from jsonb_array_elements(case when jsonb_typeof(p_payload->'writing')='array' then p_payload->'writing' else '[]'::jsonb end) w(value) where w.value->>'kind'='assignment' and coalesce(w.value->>'assignment_id','') ~ '^[0-9]{1,18}$' and char_length(trim(coalesce(w.value->>'text','')))>0;
 if v_recent+1+v_writing_count>48 then raise exception 'too many submissions today' using errcode='54000'; end if;
 insert into public.submissions(student_id,client_id,summary,payload) values(v_uid,p_client_id,p_payload->'summary',p_payload-'summary') on conflict(student_id,client_id) do nothing returning id into v_id;
 if v_id is not null then
  if jsonb_typeof(p_payload->'assignments')='object' then
   for v_entry in select key,value from jsonb_each(p_payload->'assignments') loop
    if v_entry.key ~ '^[0-9]{1,18}$' then v_assignment_id:=v_entry.key::bigint;
     select * into v_assignment from public.assignments a where a.id=v_assignment_id and not a.archived and (a.class_id is null or exists(select 1 from public.class_members cm where cm.class_id=a.class_id and cm.student_id=v_uid));
     if found then v_target:=v_assignment.target_count; v_done:=greatest(0,least(v_target,case when coalesce(v_entry.value->>'done','') ~ '^[0-9]{1,9}$' then (v_entry.value->>'done')::integer else 0 end));
      v_correct:=greatest(0,least(v_done,case when coalesce(v_entry.value->>'ok','') ~ '^[0-9]{1,9}$' then (v_entry.value->>'ok')::integer when coalesce(v_entry.value->>'correct','') ~ '^[0-9]{1,9}$' then (v_entry.value->>'correct')::integer else 0 end));
      insert into public.assignment_progress(assignment_id,student_id,done,correct,completed_at,updated_at) values(v_assignment_id,v_uid,v_done,v_correct,case when v_done>=v_target then now() else null end,now()) on conflict(assignment_id,student_id) do update set done=greatest(public.assignment_progress.done,excluded.done),correct=least(greatest(public.assignment_progress.correct,excluded.correct),greatest(public.assignment_progress.done,excluded.done)),completed_at=case when greatest(public.assignment_progress.done,excluded.done)>=v_target then coalesce(public.assignment_progress.completed_at,now()) else null end,updated_at=now();
     end if; end if; end loop;
  end if;
  if jsonb_typeof(p_payload->'assignment_progress')='array' then
   for v_entry in select value from jsonb_array_elements(p_payload->'assignment_progress') loop
    if coalesce(v_entry.value->>'assignment_id','') ~ '^[0-9]{1,18}$' then v_assignment_id:=(v_entry.value->>'assignment_id')::bigint;
     select * into v_assignment from public.assignments a where a.id=v_assignment_id and not a.archived and (a.class_id is null or exists(select 1 from public.class_members cm where cm.class_id=a.class_id and cm.student_id=v_uid));
     if found then v_target:=v_assignment.target_count; v_done:=greatest(0,least(v_target,case when coalesce(v_entry.value->>'done','') ~ '^[0-9]{1,9}$' then (v_entry.value->>'done')::integer else 0 end));
      v_correct:=greatest(0,least(v_done,case when coalesce(v_entry.value->>'correct','') ~ '^[0-9]{1,9}$' then (v_entry.value->>'correct')::integer when coalesce(v_entry.value->>'ok','') ~ '^[0-9]{1,9}$' then (v_entry.value->>'ok')::integer else 0 end));
      insert into public.assignment_progress(assignment_id,student_id,done,correct,completed_at,updated_at) values(v_assignment_id,v_uid,v_done,v_correct,case when v_done>=v_target then now() else null end,now()) on conflict(assignment_id,student_id) do update set done=greatest(public.assignment_progress.done,excluded.done),correct=least(greatest(public.assignment_progress.correct,excluded.correct),greatest(public.assignment_progress.done,excluded.done)),completed_at=case when greatest(public.assignment_progress.done,excluded.done)>=v_target then coalesce(public.assignment_progress.completed_at,now()) else null end,updated_at=now();
     end if; end if; end loop;
  end if;
  if jsonb_typeof(p_payload->'writing')='array' then
   for v_write in select value from jsonb_array_elements(p_payload->'writing') loop
    if coalesce(v_write->>'kind','')<>'assignment' or coalesce(v_write->>'assignment_id','') !~ '^[0-9]{1,18}$' or char_length(trim(coalesce(v_write->>'text','')))=0 then continue; end if;
    v_assignment_id:=(v_write->>'assignment_id')::bigint;
    select * into v_assignment from public.assignments a where a.id=v_assignment_id and not a.archived and (a.class_id is null or exists(select 1 from public.class_members cm where cm.class_id=a.class_id and cm.student_id=v_uid));
    if not found then continue; end if; v_response:=left(trim(v_write->>'text'),5000);
    begin if coalesce(v_write->>'t','') ~ '^\d{4}-\d{2}-\d{2}T' then v_submitted_at:=(v_write->>'t')::timestamptz; else v_submitted_at:=now(); end if; exception when others then v_submitted_at:=now(); end;
    v_write_client:='web-write-'||left(regexp_replace(coalesce(v_write->>'client_id',v_write->>'id',''),'[^a-zA-Z0-9_-]','','g'),50);
    if char_length(v_write_client)<8 then v_write_client:='web-write-'||md5(v_uid::text||':'||v_assignment_id::text||':'||v_submitted_at::text||':'||md5(v_response)); end if;
    insert into public.submissions(student_id,client_id,summary,payload) values(v_uid,left(v_write_client,64),jsonb_build_object('source','flutter_assignment_response','assignment_id',v_assignment_id,'assignment_title',v_assignment.title,'kind',v_assignment.kind,'skill',v_assignment.skill,'submitted_at',v_submitted_at),jsonb_build_object('assignment_response',jsonb_build_object('assignment_id',v_assignment_id,'title',v_assignment.title,'kind',v_assignment.kind,'skill',v_assignment.skill,'text',v_response,'submitted_at',v_submitted_at),'assignments',jsonb_build_object(v_assignment_id::text,jsonb_build_object('done',v_assignment.target_count,'ok',0)))) on conflict(student_id,client_id) do nothing;
   end loop;
  end if;
 end if;
 return jsonb_build_object('ok',true,'server_time',now(),'duplicate',v_id is null,'feedback',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'status',s.review_status,'note',s.review_note,'rating',s.rating,'reviewed_at',s.reviewed_at) order by s.reviewed_at) from public.submissions s where s.student_id=v_uid and s.student_seen=false),'[]'::jsonb));
end; $fn$;
create or replace function public.ack_feedback(p_ids bigint[]) returns void language sql security definer set search_path='' as $fn$ update public.submissions s set student_seen=true where s.student_id=auth.uid() and s.id=any(p_ids); $fn$;
create or replace function public.mark_notification_read(p_id bigint) returns void language plpgsql set search_path='' as $fn$ begin
 if auth.uid() is null then raise exception 'not authenticated' using errcode='28000'; end if;
 update public.notifications n set read_at=coalesce(read_at,now()) where n.id=p_id and n.user_id=auth.uid(); end; $fn$;

revoke all on function public.is_approved_student(),public.is_teacher(),public.is_staff(),public.is_class_teacher(bigint),public.is_class_member(bigint),public.create_class(text),public.assign_teacher(text),public.assign_teacher_to_class(bigint,uuid),public.assign_student_to_teacher(uuid,uuid),public.remove_student_from_teacher(uuid,uuid),public.remove_my_student(uuid),public.my_students(),public.admin_students_overview(),public.staff_audit(integer),public.my_classroom(),public.create_assignment(bigint,text,text,text,integer,timestamptz),public.assignment_status(bigint),public.update_assignment_progress(bigint,integer,integer),public.submit_progress(jsonb,text),public.ack_feedback(bigint[]),public.mark_notification_read(bigint) from public,anon;
grant execute on function public.is_approved_student(),public.is_teacher(),public.is_staff(),public.is_class_teacher(bigint),public.is_class_member(bigint),public.create_class(text),public.assign_teacher(text),public.assign_teacher_to_class(bigint,uuid),public.assign_student_to_teacher(uuid,uuid),public.remove_student_from_teacher(uuid,uuid),public.remove_my_student(uuid),public.my_students(),public.admin_students_overview(),public.staff_audit(integer),public.my_classroom(),public.create_assignment(bigint,text,text,text,integer,timestamptz),public.assignment_status(bigint),public.update_assignment_progress(bigint,integer,integer),public.submit_progress(jsonb,text),public.ack_feedback(bigint[]),public.mark_notification_read(bigint) to authenticated;
revoke all on function public.notify_assignment_recipients(),public.notify_announcement_recipients(),public.assignment_progress_events(),public.notify_written_submission(),public.notify_submission_review() from public,anon,authenticated;
revoke all on public.audit_log,public.notifications from public,anon,authenticated;
grant select on public.audit_log,public.notifications to authenticated;
grant update(read_at) on public.notifications to authenticated;
revoke all on function public.submit_progress(jsonb,text),public.ack_feedback(bigint[]) from public,anon;
grant execute on function public.submit_progress(jsonb,text),public.ack_feedback(bigint[]) to authenticated;
revoke all on function public.mark_notification_read(bigint) from public,anon;
grant execute on function public.mark_notification_read(bigint) to authenticated;
commit;